import { test } from 'node:test';
import assert from 'node:assert/strict';

test('createTodo 返回未完成的待办', async () => {
  const { createTodo } = await import('../../../src/server/todo/index.mjs').catch(() => ({}));
  if (!createTodo) return; // 实现尚未合入时跳过
  assert.deepEqual(createTodo('买牛奶'), { title: '买牛奶', done: false });
});
